<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { ElMessageBox, ElMessage } from 'element-plus'
import { request, post } from '../api/client'
interface Rule {id:string;label:string;matchType:'exact'|'prefix';userAgent:string;enabled:boolean}
interface Policy {enabled:boolean;revision:number;updatedAt:string;rules:Rule[]}
interface Observation {id:string;userAgent:string;firstSeenAt:string;lastSeenAt:string;requestCount:number;allowedCount:number;deniedCount:number;lastAllowed:boolean;lastReason:string;lastEntry:string;lastMethod:string;lastClientIp:string;lastPolicyRevision:number;whitelisted:boolean;matchedRuleId:string}
interface AccessEvent {id:string;userAgent:string;clientIp:string;entry:string;method:string;allowed:boolean;reason:string;status:number;embyUserId:string;embyUserName:string;embyVerified:boolean;createdAt:string}
const visits=ref<{items:AccessEvent[];total:number}>(),visitPage=ref(1)
async function loadVisits(){try{visits.value=await request(`/player-access/events?page=${visitPage.value}&pageSize=25&q=${encodeURIComponent(query.value)}`)}catch(e){error.value=e instanceof Error?e.message:'访问明细读取失败'}}
interface Page {items:Observation[];total:number;page:number;pageSize:number;maxRecords:number;policyRevision:number}
const policy=ref<Policy>(),records=ref<Page>(),loading=ref(false),saving=ref(false),error=ref(''),formError=ref(''),query=ref(''),filter=ref(''),page=ref(1),dialog=ref(false),details=ref<Observation>(),detailOpen=ref(false)
const observationID=ref(''),editIndex=ref(-1)
const form=reactive<Rule>({id:'',label:'',matchType:'exact',userAgent:'',enabled:true})
let epoch=0
const time=(s:string)=>new Date(s).toLocaleString('zh-CN')
const entry=(s:string)=>({strm:'STRM 解析',emby:'Emby 播放',member:'内置播放接口'})[s]||s
const reason=(s:string)=>({restriction_disabled:'限制关闭',whitelisted:'命中白名单',ua_not_whitelisted:'未匹配白名单'})[s]||s
async function load(){const token=++epoch;loading.value=true;error.value='';try{const [p,rows]=await Promise.all([request<Policy>('/player-access/policy'),request<Page>(`/player-access/observations?${new URLSearchParams({q:query.value,filter:filter.value,page:String(page.value),pageSize:'25'})}`)]);if(token!==epoch)return;policy.value=p;records.value=rows;await loadVisits()}catch(e){if(token===epoch)error.value=e instanceof Error?e.message:'播放器访问读取失败'}finally{if(token===epoch)loading.value=false}}
function search(){page.value=1;void load()}
async function savePolicy(rules:Rule[],enabled=policy.value?.enabled??false){if(!policy.value)throw new Error('请先刷新播放器策略');const p=await request<Policy>('/player-access/policy',{method:'PUT',body:JSON.stringify({enabled,revision:policy.value.revision,rules})});policy.value=p;return p}
async function toggle(){if(!policy.value)return;const enabled=!policy.value.enabled;try{await ElMessageBox.confirm(enabled?'启用后，未命中白名单的播放器将收到403，空UA也会被拒绝。请先确认真实播放器UA已加入。':'关闭后，不再按UA限制播放；媒体与文件授权检查仍然保留。',enabled?'启用播放器白名单':'关闭播放器限制',{confirmButtonText:enabled?'启用限制':'关闭限制',cancelButtonText:'取消',type:'warning'});saving.value=true;await savePolicy(policy.value.rules,enabled);ElMessage.success(enabled?'播放器白名单已启用':'UA限制已关闭，继续记录访问');await load()}catch(e){if(e==='cancel'||e==='close')return;error.value=e instanceof Error?e.message:'策略保存失败'}finally{saving.value=false}}
function edit(index=-1){observationID.value='';editIndex.value=index;formError.value='';Object.assign(form,index>=0?policy.value!.rules[index]:{id:'',label:'',matchType:'exact',userAgent:'',enabled:true});dialog.value=true}
function fromRecord(row:Observation){observationID.value=row.id;editIndex.value=-1;formError.value='';Object.assign(form,{id:'',label:'',matchType:'exact',userAgent:row.userAgent,enabled:true});dialog.value=true}
async function submit(){if(!policy.value)return;if(!form.userAgent.trim()){formError.value='空UA不能加入白名单';return}if(new TextEncoder().encode(form.userAgent).length>4096){formError.value='UA最多4096字节';return}saving.value=true;formError.value='';try{if(observationID.value){policy.value=await post('/player-access/observations/'+observationID.value+'/allow',{revision:policy.value.revision,label:form.label,confirm:true})}else{const rules=policy.value.rules.map(r=>({...r}));if(editIndex.value<0)rules.push({...form});else rules[editIndex.value]={...form};await savePolicy(rules)}dialog.value=false;ElMessage.success('UA白名单已保存，对后续播放请求生效');await load()}catch(e){formError.value=e instanceof Error?e.message:'白名单保存失败'}finally{saving.value=false}}
async function remove(index:number){if(!policy.value)return;try{await ElMessageBox.confirm('删除该规则后，如果限制已启用，依赖它的播放器将被拒绝。','删除UA白名单',{confirmButtonText:'删除规则',cancelButtonText:'取消',type:'warning'});saving.value=true;await savePolicy(policy.value.rules.filter((_,i)=>i!==index));ElMessage.success('白名单规则已删除');await load()}catch(e){if(e==='cancel'||e==='close')return;error.value=e instanceof Error?e.message:'删除失败'}finally{saving.value=false}}
async function clear(){if(!policy.value)return;try{await ElMessageBox.confirm('清理UA聚合访问记录，不删除白名单、媒体或程序原始日志。新的访问会重新记录。','清理UA访问记录',{confirmButtonText:'清理记录',cancelButtonText:'取消',type:'warning'});saving.value=true;await post('/player-access/observations/clear',{confirm:true,revision:policy.value.revision});ElMessage.success('UA访问记录已清理');await load()}catch(e){if(e==='cancel'||e==='close')return;error.value=e instanceof Error?e.message:'清理失败'}finally{saving.value=false}}
function show(row:Observation){details.value=row;detailOpen.value=true}
onMounted(load)
</script>
<template>
 <section class="page-heading"><div><span class="page-kicker">PLAYBACK / 播放器策略</span><h1>播放器访问</h1><p>记录播放入口收到的实际 User-Agent，从访问记录建立白名单。</p></div><el-button :loading="loading" @click="load">刷新访问记录</el-button></section>
 <el-alert v-if="error" :title="error" type="error" :closable="false"/>
 <section class="panel ua-policy" v-loading="loading"><div><h2>UA 白名单限制 <el-tag v-if="policy" :type="policy.enabled?'warning':'info'">{{policy.enabled?'已启用':'未启用'}}</el-tag></h2><p>{{policy?.enabled?'仅允许命中启用规则的播放器通过UA检查。':'当前仅记录访问，不按UA限制现有播放器。'}}</p><p class="field-hint">作用于本程序的 STRM、Emby 播放入口和内置播放接口；不影响后台、Emby登录、目录浏览及字幕。</p></div><el-button :type="policy?.enabled?'default':'primary'" :loading="saving" :disabled="!policy" @click="toggle">{{policy?.enabled?'关闭UA限制':'启用UA限制'}}</el-button></section>
 <section class="panel section-gap"><div class="panel-title"><div><h2>播放器白名单</h2><p class="field-hint">区分大小写，完整匹配为默认；前缀匹配可显式覆盖播放器版本变化。</p></div><el-button :disabled="!policy||saving" @click="edit()">手动添加UA</el-button></div><div v-if="policy?.rules.length" class="rule-list"><article v-for="(rule,index) in policy.rules" :key="rule.id"><div class="rule-copy"><div class="rule-heading"><strong>{{rule.label||'未命名规则'}}</strong><el-tag size="small">{{rule.matchType==='exact'?'完整匹配':'前缀匹配'}}</el-tag><el-tag v-if="!rule.enabled" type="info" size="small">已停用</el-tag></div><code>{{rule.userAgent}}</code></div><div class="rule-actions"><el-button :disabled="saving" @click="edit(index)">编辑规则</el-button><el-button type="danger" plain :disabled="saving" @click="remove(index)">删除</el-button></div></article></div><el-empty v-else-if="!loading" description="尚未添加UA白名单"><p class="field-hint">先让播放器发起一次播放，再从下方记录加入，或手动输入完整UA。</p></el-empty></section>
 <section class="panel section-gap"><div class="panel-title"><div><h2>UA 访问记录</h2><p class="field-hint">相同完整UA聚合统计，保留最近 {{records?.maxRecords||2000}} 种。通过数量仅表示通过UA检查，不代表身份授权或播放成功。</p></div><el-button type="danger" plain :disabled="saving||!records?.total" @click="clear">清理UA记录</el-button></div><form class="ua-filter" @submit.prevent="search"><el-input v-model="query" aria-label="搜索UA记录" placeholder="输入播放器UA关键词" clearable maxlength="200"/><el-select v-model="filter" placeholder="全部访问" aria-label="UA记录筛选" @change="search"><el-option label="全部访问" value=""/><el-option label="已在白名单" value="whitelisted"/><el-option label="未在白名单" value="unlisted"/></el-select><el-button native-type="submit" :loading="loading">搜索记录</el-button></form>
 <div class="ua-table" v-loading="loading"><el-table :data="records?.items||[]" empty-text="尚无符合条件的UA访问记录"><el-table-column label="播放器 UA" min-width="330"><template #default="{row}"><code class="ua-preview">{{row.userAgent||'（空 UA）'}}</code><el-tag size="small" :type="row.whitelisted?'success':'info'">{{row.whitelisted?'已在白名单':'未在白名单'}}</el-tag></template></el-table-column><el-table-column label="访问 / 通过 / 拒绝" min-width="165"><template #default="{row}">{{row.requestCount}} / {{row.allowedCount}} / {{row.deniedCount}}<p class="field-hint">{{reason(row.lastReason)}}</p></template></el-table-column><el-table-column label="访问IP" min-width="145"><template #default="{row}"><code>{{row.lastClientIp||'未知'}}</code></template></el-table-column><el-table-column label="最近访问" min-width="180"><template #default="{row}">{{time(row.lastSeenAt)}}<p class="field-hint">{{entry(row.lastEntry)}} · {{row.lastMethod}}</p></template></el-table-column><el-table-column label="操作" width="218"><template #default="{row}"><div class="record-actions"><el-button @click="show(row)">查看UA</el-button><el-button :disabled="saving||!row.userAgent||row.whitelisted||!policy" @click="fromRecord(row)">加入白名单</el-button></div></template></el-table-column></el-table></div>
 <ul class="ua-mobile" v-loading="loading"><li v-for="row in records?.items" :key="row.id"><code>{{row.userAgent||'（空 UA）'}}</code><div><el-tag size="small" :type="row.whitelisted?'success':'info'">{{row.whitelisted?'已在白名单':'未在白名单'}}</el-tag><span>{{reason(row.lastReason)}}</span></div><p class="field-hint">访问IP：{{row.lastClientIp||'未知'}}</p><p>访问 {{row.requestCount}} · 通过 {{row.allowedCount}} · 拒绝 {{row.deniedCount}}</p><p class="field-hint">{{time(row.lastSeenAt)}} · {{entry(row.lastEntry)}}</p><div class="record-actions"><el-button @click="show(row)">查看UA</el-button><el-button :disabled="saving||!row.userAgent||row.whitelisted||!policy" @click="fromRecord(row)">加入白名单</el-button></div></li></ul><el-pagination v-if="records&&records.total>25" v-model:current-page="page" :total="records.total" :page-size="25" layout="prev,pager,next,total" @current-change="load"/></section>
 <section class="panel section-gap access-events"><div class="panel-title"><div><h2>逐次访问 / Emby用户</h2><p class="field-hint">最多保留10000次；用户身份须由Emby服务端核验。STRM独立请求或未核验请求不根据UA/IP关联用户。</p></div><el-button @click="loadVisits">刷新访问明细</el-button></div><article v-for="visit in visits?.items" :key="visit.id"><div><strong>{{visit.embyVerified?(visit.embyUserName||visit.embyUserId):'Emby用户未核验 / 不适用'}}</strong><el-tag :type="visit.allowed?'info':'warning'">{{visit.status||'处理中'}} · {{reason(visit.reason)}}</el-tag></div><p>访问IP {{visit.clientIp}} · {{entry(visit.entry)}} · {{visit.method}} · {{time(visit.createdAt)}}</p><code>{{visit.userAgent||'（空UA）'}}</code><small v-if="visit.embyVerified">已核验用户ID {{visit.embyUserId}}</small></article><el-empty v-if="!visits?.items.length" description="暂无逐次播放访问"/><el-pagination v-if="visits&&visits.total>25" v-model:current-page="visitPage" :total="visits.total" :page-size="25" layout="prev,pager,next,total" @current-change="loadVisits"/></section>
 <section class="note-panel"><strong>UA限制不是强身份认证</strong><p>客户端可以声明或伪装UA，白名单用于限制播放器使用方式，不能代替用户及文件权限。已发出的115 CDN链接不受此处规则追溯撤销。规则不会替换实际请求UA，也不会改写原STRM或恢复服务器媒体中转。</p><p v-if="policy" class="field-hint">策略修订 {{policy.revision}} · {{time(policy.updatedAt)}}</p></section>
 <el-dialog v-model="dialog" :title="observationID?'从访问记录加入白名单':editIndex>=0?'编辑UA规则':'添加UA规则'" width="min(680px,94vw)" :close-on-click-modal="false"><el-alert v-if="formError" :title="formError" type="error" :closable="false"/><el-form label-position="top" @submit.prevent="submit"><el-form-item label="播放器备注" for="ua-label"><el-input id="ua-label" v-model="form.label" maxlength="80" placeholder="例如：客厅 SenPlayer"/></el-form-item><el-form-item label="完整 User-Agent" for="ua-value"><el-input id="ua-value" v-model="form.userAgent" type="textarea" :rows="5" :readonly="!!observationID" placeholder="填写实际UA，不会去除首尾空格"/></el-form-item><template v-if="!observationID"><el-form-item label="匹配方式"><el-radio-group v-model="form.matchType" aria-label="UA匹配方式"><el-radio value="exact">完整匹配</el-radio><el-radio value="prefix">前缀匹配</el-radio></el-radio-group></el-form-item><el-form-item label="规则启用"><el-switch v-model="form.enabled" aria-label="启用UA规则"/></el-form-item></template><p class="field-hint">{{observationID?'使用记录中的原始UA添加完整匹配规则，不自动开启全局限制。':form.matchType==='prefix'?'区分大小写的字面前缀，至少3字节；不是通配符或正则。选择过短前缀可能允许多个播放器。':'区分大小写、逐字完整匹配，播放器UA版本变化后需要新增或修改规则。'}}</p></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="submit">{{observationID?'确认加入白名单':'保存UA规则'}}</el-button></template></el-dialog>
 <el-dialog v-model="detailOpen" title="完整UA访问信息" width="min(720px,94vw)"><template v-if="details"><label for="ua-detail">实际收到的完整 UA</label><el-input id="ua-detail" :model-value="details.userAgent" type="textarea" :rows="5" readonly/><dl class="ua-detail"><div><dt>首次访问</dt><dd>{{time(details.firstSeenAt)}}</dd></div><div><dt>最近访问</dt><dd>{{time(details.lastSeenAt)}}</dd></div><div><dt>连接来源IP</dt><dd>{{details.lastClientIp}}</dd></div><div><dt>播放入口</dt><dd>{{entry(details.lastEntry)}} · {{details.lastMethod}}</dd></div><div><dt>最近UA检查</dt><dd>{{reason(details.lastReason)}} · 策略 {{details.lastPolicyRevision}}</dd></div><div><dt>累计统计</dt><dd>访问 {{details.requestCount}} / 通过 {{details.allowedCount}} / 拒绝 {{details.deniedCount}}</dd></div></dl></template><template #footer><el-button @click="detailOpen=false">关闭</el-button><el-button v-if="details&&!details.whitelisted&&details.userAgent" @click="detailOpen=false;fromRecord(details)">从此记录加入白名单</el-button></template></el-dialog>
</template>
<style scoped>
.ua-policy{margin-bottom:24px;display:flex;align-items:center;justify-content:space-between;gap:24px}.ua-policy h2{display:flex;align-items:center;gap:12px}.ua-policy p{color:var(--muted);line-height:1.8}.rule-list article{display:flex;align-items:center;justify-content:space-between;gap:24px;padding:20px 0;border-bottom:1px solid var(--border)}.rule-list article:last-child{border:0}.rule-copy{min-width:0}.rule-heading{display:flex;align-items:center;flex-wrap:wrap;gap:10px;margin-bottom:12px}.rule-copy code,.ua-mobile code{display:block;overflow-wrap:anywhere;white-space:pre-wrap;font-size:13px;line-height:1.7}.rule-actions,.record-actions{display:flex;gap:8px;flex-shrink:0}.rule-actions .el-button,.record-actions .el-button{margin:0}.ua-filter{display:flex;align-items:center;gap:12px;margin:20px 0}.ua-filter .el-input{flex:1}.ua-filter .el-select{width:170px}.ua-table{overflow:auto}.ua-table .el-table{min-width:850px}.ua-preview{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;overflow-wrap:anywhere;font-size:12px;line-height:1.7;margin-bottom:8px}.ua-mobile{display:none;list-style:none;padding:0;margin:0}.ua-detail div{display:flex;justify-content:space-between;gap:20px;padding:12px 0;border-bottom:1px solid var(--border)}.ua-detail dt{color:var(--muted)}.ua-detail dd{margin:0;text-align:right;overflow-wrap:anywhere}.el-pagination{overflow:auto;margin-top:20px}@media(max-width:700px){.ua-policy,.rule-list article{align-items:flex-start;flex-direction:column;gap:12px}.ua-filter{flex-wrap:wrap}.ua-filter .el-input{flex-basis:100%}.ua-filter .el-select{flex:1}.ua-table{display:none}.ua-mobile{display:block}.ua-mobile li{padding:20px 0;border-bottom:1px solid var(--border)}.ua-mobile li>div{display:flex;flex-wrap:wrap;gap:12px;margin-top:12px}.ua-mobile p{font-size:13px;line-height:1.7}.ua-mobile .el-button,.rule-actions .el-button{min-height:44px}.panel-title{align-items:flex-start;flex-wrap:wrap}.ua-detail div{flex-direction:column;gap:8px}.ua-detail dd{text-align:left}}
</style>

<style scoped>.access-events article{padding:20px 0;border-bottom:1px solid var(--border)}.access-events article>div{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}.access-events p,.access-events small{color:var(--muted);line-height:1.7}.access-events code{display:block;overflow-wrap:anywhere;font-size:12px;line-height:1.8}.access-events small{display:block;margin-top:8px}</style>
